mapper.select:
SELECT f.faq_sq AS faqSq, f.faq_type_cd AS faqTypeCd, c.common_code_nm AS categoryNm, f.question_ttl AS questionTtl, f.faq_created_at_dtm AS faqCreatedAtDtm, f.faq_modified_at_dtm AS modifiedAt, f.faq_is_deleted_yn AS isDeletedYn FROM tbl_faq_m f LEFT JOIN tbl_common_code_c c ON f.faq_type_cd = c.common_code_sq WHERE f.faq_is_deleted_yn = 'N'
AND f.faq_type_cd = #{request.faqTypeCd}
AND (f.question_ttl LIKE CONCAT('%', #{request.keyword}, '%') OR f.answer_cn LIKE CONCAT('%', #{request.keyword}, '%'))
ORDER BY f.faq_sq DESC LIMIT #{request.size} OFFSET #{request.offset}

SELECT COUNT(*) FROM tbl_faq_m WHERE faq_is_deleted_yn = 'N'
AND faq_type_cd = #{request.faqTypeCd}
AND (question_ttl LIKE CONCAT('%', #{request.keyword}, '%') OR answer_cn LIKE CONCAT('%', #{request.keyword}, '%'))
